(43897, '_transient_code_snippets_welcome_data', 'a:5:{s:6:\"banner\";a:9:{s:3:\"key\";s:12:\"backtonormal\";s:14:\"start_datetime\";O:17:\"DateTimeImmutable\":3:{s:4:\"date\";s:26:\"2025-01-24 07:00:00.000000\";s:13:\"timezone_type\";i:3;s:8:\"timezone\";s:3:\"UTC\";}s:12:\"end_datetime\";O:17:\"DateTimeImmutable\":3:{s:4:\"date\";s:26:\"2025-07-05 16:00:00.000000\";s:13:\"timezone_type\";i:3;s:8:\"timezone\";s:3:\"UTC\";}s:9:\"text_free\";s:79:\"Code Without Limits – Experience Ultimate Flexibility with Code Snippets Pro!\";s:15:\"action_url_free\";s:22:\"https://snipco.de/TFHM\";s:17:\"action_label_free\";s:10:\"Go Pro now\";s:8:\"text_pro\";s:73:\"Enjoying the Power of Pro? Make It Yours Forever with a Lifetime Upgrade!\";s:14:\"action_url_pro\";s:22:\"https://snipco.de/TFIP\";s:16:\"action_label_pro\";s:10:\"Go Pro now\";}s:9:\"hero-item\";a:3:{s:4:\"name\";s:26:\"Code Snippet AI is here…\";s:10:\"follow_url\";s:54:\"https://codesnippets.pro/blog/code-snippet-ai-is-here/\";s:9:\"image_url\";s:71:\"https://codesnippets.pro/wp-content/uploads/2024/05/cs_ai_demo_full.gif\";}s:8:\"features\";a:4:{i:0;a:5:{s:5:\"title\";s:28:\"Pssss... Get Secret Discount\";s:10:\"follow_url\";s:22:\"https://snipco.de/TFIG\";s:9:\"image_url\";s:81:\"https://codesnippets.pro/wp-content/uploads/2024/09/Promotions_Hero_All_Plans.png\";s:8:\"category\";s:5:\"offer\";s:11:\"description\";s:100:\"Get secret discount on all Code Snippets Pro plans. Just use coupon code \'General5\' at the checkout!\";}i:1;a:5:{s:5:\"title\";s:25:\"Add Unsplash to WordPress\";s:10:\"follow_url\";s:22:\"https://snipco.de/Mind\";s:9:\"image_url\";s:53:\"https://i3.ytimg.com/vi/kRSwWDanX0A/maxresdefault.jpg\";s:8:\"category\";s:3:\"tip\";s:11:\"description\";s:70:\"Code Snippet to Add Unsplash to WordPress - Find and Download Images..\";}i:2;a:5:{s:5:\"title\";s:30:\"Code Snippet Cloud Setup Guide\";s:10:\"follow_url\";s:22:\"https://snipco.de/Mine\";s:9:\"image_url\";s:149:\"https://cdn.getgist.com/attachment_images/76ca6cef08ca8e69ac1e7fbc15004bebbd08ad595ee67e0d7b55d1a9555354bfScreenshot%202023-11-23%20at%2000.50.02.png\";s:8:\"category\";s:5:\"guide\";s:11:\"description\";s:143:\"We have done our best to make the cloud set up as smooth and easy as possible. This guide below will walk you through the process step by step.\";}i:3;a:5:{s:5:\"title\";s:14:\"Cloud and AI +\";s:10:\"follow_url\";s:22:\"https://snipco.de/Minf\";s:9:\"image_url\";s:53:\"https://i3.ytimg.com/vi/rEOC2bIwY-w/maxresdefault.jpg\";s:8:\"category\";s:11:\"new feature\";s:11:\"description\";s:68:\"Code Snippets 3.6 Announcement - AI CodeSnippets - Generate AI Code!\";}}s:8:\"partners\";a:4:{i:0;a:3:{s:5:\"title\";s:9:\"Elementor\";s:10:\"follow_url\";s:22:\"https://snipco.de/KK3d\";s:9:\"image_url\";s:76:\"https://codesnippets.pro/wp-content/uploads/2024/05/Elementor-logo-green.png\";}i:1;a:3:{s:5:\"title\";s:7:\"InstaWP\";s:10:\"follow_url\";s:22:\"https://snipco.de/KK3n\";s:9:\"image_url\";s:68:\"https://codesnippets.pro/wp-content/uploads/2024/05/instawp-logo.png\";}i:2;a:3:{s:5:\"title\";s:8:\"Codeable\";s:10:\"follow_url\";s:22:\"https://snipco.de/KK3j\";s:9:\"image_url\";s:69:\"https://codesnippets.pro/wp-content/uploads/2024/05/codeable-logo.png\";}i:3;a:3:{s:5:\"title\";s:10:\"Crocoblock\";s:10:\"follow_url\";s:22:\"https://snipco.de/KK3l\";s:9:\"image_url\";s:71:\"https://codesnippets.pro/wp-content/uploads/2024/05/crocoblock-logo.png\";}}s:9:\"changelog\";a:4:{s:5:\"3.6.8\";a:4:{s:5:\"Added\";a:1:{s:4:\"core\";a:1:{i:0;s:87:\"`code_snippets/hide_welcome_banner` filter hook for hiding welcome banner in dashboard.\";}}s:7:\"Changed\";a:1:{s:3:\"pro\";a:1:{i:0;s:43:\"Updated Freemius SDK to the latest version.\";}}s:7:\"Removed\";a:1:{s:4:\"core\";a:1:{i:0;s:122:\"Functionality allowing `[code_snippet]` shortcodes to be embedded recursively – it will be re-added in a future version.\";}}s:5:\"Fixed\";a:2:{s:4:\"core\";a:4:{i:0;s:80:\"Shortcodes embedded within `[code_snippet]` shortcodes not evaluating correctly.\";i:1;s:92:\"Translation functions being called too early in some instances when loading plugin settings.\";i:2;s:71:\"Incorrect arrow entity used in cloud list table (props to [brandonjp]).\";i:3;s:69:\"Removed reference to missing plugins.css file in core plugin version.\";}s:3:\"pro\";a:1:{i:0;s:46:\"\'Generate\' button not appearing on some sites.\";}}}s:5:\"3.6.7\";a:3:{s:5:\"Added\";a:1:{s:4:\"core\";a:2:{i:0;s:90:\"Generated snippet shortcode tags will include the snippet name, for easier identification.\";i:1;s:130:\"Admin notices will dismiss automatically after five seconds. ([#208](https://github.com/codesnippetspro/code-snippets/issues/208))\";}}s:7:\"Changed\";a:1:{s:4:\"core\";a:3:{i:0;s:40:\"Updated CSS to use latest Sass features.\";i:1;s:161:\"Moved theme selector to just above editor preview on settings page (thanks to [brandonjp]). ([#206](https://github.com/codesnippetspro/code-snippets/issues/206))\";i:2;s:134:\"`[code_snippet]` shortcodes can now be nested within each other. ([#198](https://github.com/codesnippetspro/code-snippets/issues/198))\";}}s:5:\"Fixed\";a:2:{s:3:\"pro\";a:2:{i:0;s:144:\"Save buttons above editor did not follow usual validation process in Pro.  ([#197](https://github.com/codesnippetspro/code-snippets/issues/197))\";i:1;s:111:\"Issue with Elementor source code widget.  ([#205](https://github.com/codesnippetspro/code-snippets/issues/205))\";}s:4:\"core\";a:5:{i:0;s:69:\"Minor inconsistencies in consistent UI elements between Core and Pro.\";i:1;s:100:\"Tags input not allowing input. ([#211](https://github.com/codesnippetspro/code-snippets/issues/211))\";i:2;s:67:\"Snippet descriptions not visible when viewing cloud search results.\";i:3;s:76:\"Snippet import page not displaying number of successfully imported snippets.\";i:4;s:60:\"Use UTC time when deciding when to display campaign notices.\";}}}s:7:\"3.6.6.1\";a:1:{s:5:\"Fixed\";a:2:{s:4:\"core\";a:1:{i:0;s:79:\"Redeployment of [v3.6.6](#366-2024-11-27) to overcome issue with initial build.\";}s:3:\"pro\";a:1:{i:0;s:36:\"Type issue when caching cloud links.\";}}}s:5:\"3.6.6\";a:2:{s:7:\"Changed\";a:1:{s:4:\"core\";a:4:{i:0;s:51:\"Improved compatability with modern versions of PHP.\";i:1;s:46:\"Extended welcome API to include admin notices.\";i:2;s:111:\"Action hook `code_snippets/update_snippet` now only includes the snippet ID instead of the full snippet object.\";i:3;s:80:\"Action hook `code_snippets/admin/manage` now includes the currently viewed type.\";}}s:5:\"Fixed\";a:1:{s:4:\"core\";a:5:{i:0;s:86:\"Memory issue from checking aggregate posts while loading front-end syntax highlighter.\";i:1;s:98:\"Translation functions being called too early on upgrade, resulting in localisation loading errors.\";i:2;s:89:\"Bug preventing the \'share on network\' status of network snippets from correctly updating.\";i:3;s:98:\"Incorrect logic controlling when to display \'Save Changes\' or \'Save Changes and Activate\' buttons.\";i:4;s:76:\"Old notices persisting when switching between editing and creating snippets.\";}}}}}', 'off'),
