(87, 1, '2025-02-04 13:26:57', '2025-02-04 13:26:57', '<!-- wp:template-part {\"slug\":\"main-header\",\"theme\":\"garden-plant-shop\",\"tagName\":\"header\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"layout\":{\"inherit\":\"true\",\"type\":\"constrained\"}} -->\n<main class=\"wp-block-group\"><!-- wp:cover {\"dimRatio\":0,\"minHeight\":975,\"minHeightUnit\":\"px\",\"isDark\":false,\"className\":\"alignfull\"} -->\n<div class=\"wp-block-cover is-light alignfull\" style=\"min-height:975px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"700\",\"fontSize\":\"20px\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|primary\"}}}},\"textColor\":\"primary\",\"fontFamily\":\"abhaya-libre\"} -->\n<h4 class=\"wp-block-heading has-primary-color has-text-color has-link-color has-abhaya-libre-font-family\" style=\"font-size:20px;font-style:normal;font-weight:700\"><strong>Obezbedi sebi...</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"700\",\"fontSize\":\"45px\"}},\"textColor\":\"heading\",\"fontFamily\":\"abhaya-libre\"} -->\n<h2 class=\"wp-block-heading has-heading-color has-text-color has-abhaya-libre-font-family\" style=\"font-size:45px;font-style:normal;font-weight:700\">Kvalitetne sadnice za svaki kutak</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|body-text\"}}}},\"textColor\":\"body-text\",\"fontSize\":\"upper-heading\",\"fontFamily\":\"abhaya-libre\"} -->\n<p class=\"has-body-text-color has-text-color has-link-color has-abhaya-libre-font-family has-upper-heading-font-size\">Naša firma je posvećena uzgajanju i prodaji visokokvalitetnih sadnica, pružajući ljubiteljima biljaka sve što im je potrebno za stvaranje zelenih oaza u svojim domovima i vrtovima.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"blockGap\":\"0\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"fontFamily\":\"abhaya-libre\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"flexWrap\":\"nowrap\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons has-abhaya-libre-font-family\" style=\"margin-top:0;margin-bottom:0\"><!-- wp:button {\"className\":\"is-style-fill\",\"style\":{\"border\":{\"radius\":\"10px\"}},\"fontFamily\":\"abhaya-libre\"} -->\n<div class=\"wp-block-button is-style-fill has-abhaya-libre-font-family\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/wordpress/blog/\" style=\"border-radius:10px\">READ MORE</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"60%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:60%\"><!-- wp:image {\"id\":7,\"width\":\"735px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://localhost/wordpress/wp-content/themes/garden-plant-shop/assets/images/slider-image.png\" alt=\"\" class=\"wp-image-7\" style=\"width:735px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"style\":{\"border\":{\"radius\":\"0px\"}}} -->\n<div class=\"wp-block-columns\" style=\"border-radius:0px\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"contact-box\",\"style\":{\"border\":{\"radius\":\"20px\"}},\"backgroundColor\":\"primary\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center contact-box has-primary-background-color has-background\" style=\"border-radius:20px\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading {\"level\":3,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}},\"typography\":{\"fontSize\":\"25px\"},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"textColor\":\"white\",\"fontFamily\":\"abhaya-libre\"} -->\n<h3 class=\"wp-block-heading has-white-color has-text-color has-link-color has-abhaya-libre-font-family\" style=\"margin-top:0;margin-bottom:0;font-size:25px\"><strong>Misija</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"textColor\":\"white\",\"fontSize\":\"upper-heading\",\"fontFamily\":\"abhaya-libre\"} -->\n<p class=\"has-white-color has-text-color has-link-color has-abhaya-libre-font-family has-upper-heading-font-size\" style=\"margin-top:0;margin-bottom:0\">Naša misija je da obogatimo životni prostor naših kupaca kroz ponudu zdravih i pažljivo uzgojenih sadnica, pružajući stručne savete i podršku za njihov pravilan rast i razvoj.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}},\"typography\":{\"fontSize\":\"25px\"},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"textColor\":\"white\",\"fontFamily\":\"abhaya-libre\"} -->\n<h3 class=\"wp-block-heading has-white-color has-text-color has-link-color has-abhaya-libre-font-family\" style=\"margin-top:0;margin-bottom:0;font-size:25px\"><strong>Vizija</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"textColor\":\"white\",\"fontSize\":\"upper-heading\",\"fontFamily\":\"abhaya-libre\"} -->\n<p class=\"has-white-color has-text-color has-link-color has-abhaya-libre-font-family has-upper-heading-font-size\" style=\"margin-top:0;margin-bottom:0\">Težimo da postanemo vodeći izbor za entuzijaste biljaka, prepoznati po kvalitetu naših proizvoda, ekološkoj odgovornosti i posvećenosti unapređenju zelenih površina u zajednici.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:33.33%\"><!-- wp:image {\"id\":13,\"width\":\"56px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"right\"} -->\n<figure class=\"wp-block-image alignright size-full is-resized\"><img src=\"http://localhost/wordpress/wp-content/themes/garden-plant-shop/assets/images/call-icon.png\" alt=\"\" class=\"wp-image-13\" style=\"width:56px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"66.66%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:66.66%\"><!-- wp:heading {\"level\":5,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"textColor\":\"white\",\"fontFamily\":\"abhaya-libre\"} -->\n<h5 class=\"wp-block-heading has-white-color has-text-color has-link-color has-abhaya-libre-font-family\" style=\"margin-top:0;margin-bottom:0\">Kontaktiraj nas</h5>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"}}},\"typography\":{\"fontSize\":\"25px\"},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"textColor\":\"white\",\"fontFamily\":\"abhaya-libre\"} -->\n<p class=\"has-white-color has-text-color has-link-color has-abhaya-libre-font-family\" style=\"margin-top:0;margin-bottom:0;font-size:25px\"><strong>+381655053505</strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover --></main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer-columns\",\"theme\":\"garden-plant-shop\",\"tagName\":\"footer\"} /-->', 'Front Page', 'Displays your site\'s homepage, whether it is set to display latest posts or a static page. The Front Page template takes precedence over all templates.', 'publish', 'closed', 'closed', '', 'front-page', '', '', '2025-02-10 16:38:42', '2025-02-10 16:38:42', '', 0, 'http://localhost/wordpress/2025/02/04/front-page/', 0, 'wp_template', '', 0),
